#include "arkime.h"

extern ArkimeConfig_t        config;

LOCAL int clientIdField;
LOCAL int topicField;
LOCAL int versionField;
LOCAL int typeField;
LOCAL int userField;
LOCAL int willTopicField;
LOCAL int qosField;
LOCAL int flagsField;
LOCAL int connackCodeField;

// MQTT packet types
LOCAL const char *mqttTypes[] = {
    "Reserved",      // 0
    "CONNECT",       // 1
    "CONNACK",       // 2
    "PUBLISH",       // 3
    "PUBACK",        // 4
    "PUBREC",        // 5
    "PUBREL",        // 6
    "PUBCOMP",       // 7
    "SUBSCRIBE",     // 8
    "SUBACK",        // 9
    "UNSUBSCRIBE",   // 10
    "UNSUBACK",      // 11
