#!/usr/bin/env python3
"""Replicate the normalization tests.pl --fix applies to capture --tests JSON.

Used only locally to (re)generate the .test golden files because the Perl
module toolchain is unavailable in this environment. The sorting rules mirror
sortObj/sortJson/fix in tests/tests.pl.
"""

import json
import sys


def sort_obj(parent_key, obj):
    for key in list(obj.keys()):
        value = obj[key]
        if isinstance(value, dict):
            sort_obj(key, value)
        elif isinstance(value, list):
            if key in ("dns",):
                for dns_obj in value:
                    sort_obj(key, dns_obj)
            if len(value) < 2:
                continue
            if key in ("packetPos", "packetLen", "cert", "dns"):
                continue
            if f"{parent_key}.{key}" in ("dns.answers", "vlan.id"):
                continue
            if f"{parent_key}.{key}" in ("http.statuscode", "icmp.type", "icmp.code"):
                obj[key] = sorted(value)
            elif key == "zeekintel":
                obj[key] = sorted(
                    value,
                    key=lambda item: (
                        item.get("indicator_type", ""),
                        item.get("indicator", ""),
                        item.get("where", ""),
                        item.get("source", ""),
                    ),
                )
            else:
                obj[key] = sorted(value, key=lambda item: ("" if item is None else str(item), item))


def session_key(session):
    body = session["body"]
    return (
        body["firstPacket"],
        body["lastPacket"],
        body["source"]["port"],
        body["source"].get("ip", ""),
        body["destination"].get("port", 0),
        body["destination"].get("ip", ""),
    )


def normalize(data):
    for session in data["sessions3"]:
        sort_obj("", session["body"])
    data["sessions3"].sort(key=session_key)
    for session in data["sessions3"]:
        body = session["body"]
        session["header"]["index"].pop("_id", None)
        for key in ("rootId", "timestamp", "@timestamp"):
            if key in body:
                body[key] = "SET"
    return data


class PerlStyleEncoder(json.JSONEncoder):
    # JSON::PP pretty output: 1-space indentation, "key" : value spacing,
    # and empty arrays/objects on one line.

    def encode(self, obj):
        return self._encode(obj, 0)

    def _encode(self, obj, depth):
        indent = " " * (depth + 1)
        if isinstance(obj, dict):
            if not obj:
                return "{}"
            parts = []
            for key in obj:
                parts.append(
                    f'{indent}{json.dumps(key)} : {self._encode(obj[key], depth + 1)}'
                )
            return "{\n" + ",\n".join(parts) + "\n" + " " * depth + "}"
        if isinstance(obj, list):
            if not obj:
                return "[]"
            parts = [f"{indent}{self._encode(item, depth + 1)}" for item in obj]
            return "[\n" + ",\n".join(parts) + "\n" + " " * depth + "]"
        return json.dumps(obj)


if __name__ == "__main__":
    raw = open(sys.argv[1]).read()
    data, _ = json.JSONDecoder().raw_decode(raw)
    normalize(data)
    print(PerlStyleEncoder().encode(data))

